def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D'

    total_opp_c = sum(1 for h in history if h[1] == 'C')
    total_opp_d = n - total_opp_c

    if n == 2:
        if (history[0][0] == 'C' and history[0][1] == 'C' and
                history[1][0] == 'D' and history[1][1] == 'D'):
            return 'C'
        if total_opp_d == 0:
            return 'C'

    w = n if n < 12 else 12

    recent_c = sum(1 for i in range(n - w, n) if history[i][1] == 'C')
    recent_rate = recent_c / w

    after_c_count = 0
    after_c_coop = 0
    after_d_count = 0
    after_d_coop = 0

    overall_punished = 0
    overall_forgiven = 0
    overall_unprovoked = 0

    for i in range(1, n):
        prev_my = history[i - 1][0]
        opp_action = history[i][1]

        if prev_my == 'C':
            after_c_count += 1
            if opp_action == 'C':
                after_c_coop += 1
            else:
                overall_unprovoked += 1
        else:
            after_d_count += 1
            if opp_action == 'C':
                after_d_coop += 1
                overall_forgiven += 1
            else:
                overall_punished += 1

    if after_c_count > 0:
        p_c_if_C = after_c_coop / after_c_count
    else:
        p_c_if_C = 1.0

    if after_d_count > 0:
        p_c_if_D = after_d_coop / after_d_count
    else:
        p_c_if_D = 0.0

    if (overall_punished == 0 and overall_forgiven > 0 and
            overall_unprovoked == 0 and recent_rate >= 0.75):
        return 'D'

    start = n - w
    if start < 1:
        start = 1

    recent_punished = 0
    recent_forgiven = 0
    recent_unprovoked = 0

    for i in range(start, n):
        prev_my = history[i - 1][0]
        opp_action = history[i][1]

        if prev_my == 'D':
            if opp_action == 'D':
                recent_punished += 1
            else:
                recent_forgiven += 1
        else:
            if opp_action == 'D':
                recent_unprovoked += 1

    streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak += 1
        i -= 1

    last_opp = history[-1][1]
    overall_rate = total_opp_c / n

    if last_opp == 'D':
        if overall_unprovoked == 0 and overall_punished > 0 and recent_rate >= 0.5:
            return 'C'

        if streak == 1:
            if recent_punished > 0 and recent_unprovoked == 0 and recent_rate >= 0.5:
                return 'C'
            if overall_rate >= 0.7 and recent_rate >= 0.6 and recent_unprovoked <= 1:
                return 'C'
            if p_c_if_C >= 0.75 and overall_unprovoked <= 2 and recent_rate >= 0.5:
                return 'C'
            return 'D'

        if streak == 2:
            if recent_rate >= 0.65 and recent_unprovoked == 0 and overall_rate >= 0.5:
                return 'C'
            return 'D'

        if overall_rate >= 0.85 and recent_rate >= 0.55 and recent_unprovoked <= 1:
            return 'C'
        return 'D'

    if recent_rate <= 0.35:
        return 'D'

    if overall_rate <= 0.25 and recent_rate <= 0.55:
        return 'D'

    if (n >= 8 and overall_unprovoked == 0 and overall_punished > 0 and
            recent_punished == 0 and recent_unprovoked == 0 and
            recent_forgiven >= 2 and p_c_if_D >= 0.7):
        return 'D'

    if n >= 90:
        if recent_rate >= 0.5:
            return 'C'
        return 'D'

    return 'C'
